namespace {
void printUsage()
{
    qDebug() << "Usage: ./dots <id> [-lssd <threshold>] [--dist]";
    qDebug() << "  <id>             Read input from data/<id>/original.txt (resolved absolutely)";
    qDebug() << "  -lssd <thresh>   Override the LSSD threshold (default 0.05)";
    qDebug() << "  --dist           After output, compute Frechet distance via ./frechet";
    qDebug() << "  -h, --help       Show this help and exit";
}
} // namespace

int main(int argc, char *argv[])
{
    QCoreApplication a(argc, argv);

    if (argc < 2) {
        printUsage();
        return 1;
    }

    if (QString(argv[1]) == "-h" || QString(argv[1]) == "--help") {
        printUsage();
        return 0;
    }

    const QString id = argv[1];
    double lssdThreshold = 0.05;
    bool calculateDistance = false;

    for (int argIndex = 2; argIndex < argc; ++argIndex) {
        const QString argument = argv[argIndex];
        if (argument == "--dist") {
            calculateDistance = true;
        } else if (argument == "-h" || argument == "--help") {
            printUsage();
            return 0;
        } else if (argument == "-lssd") {
            if (argIndex + 1 >= argc) {
                qCritical() << "Error: -lssd requires a positive threshold.";
                return 1;
            }

            bool ok = false;
            const double value = QString(argv[++argIndex]).toDouble(&ok);
            if (!ok || value <= 0) {
                qCritical() << "Error: -lssd requires a positive numeric threshold.";
                return 1;
            }
            lssdThreshold = value;
        } else {
            qCritical() << "Error: Unknown argument:" << argument;
            printUsage();
            return 1;
        }
    }

